package tokenizer

import java.time.{LocalDate, LocalDateTime, format}
import java.time.format.DateTimeFormatter
import scala.collection.mutable
import scala.util.{Try, Success, Failure}
import io.circe.Json
import io.circe.syntax._
import io.circe.parser._

// ============================================================================
// Protocol definitions
// ============================================================================

trait Tokenizable {
  def toToken: String
}

trait HasLength {
  def length: Int
}

trait TokenProcessor[-T] {
  def process(item: T): Unit
}

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object STRING extends TokenType { val value = "string" }
  case object NUMERIC extends TokenType { val value = "numeric" }
  case object TEMPORAL extends TokenType { val value = "temporal" }
  case object STRUCTURED extends TokenType { val value = "structured" }
  case object BINARY extends TokenType { val value = "binary" }
  case object NULL extends TokenType { val value = "null" }
}

// ============================================================================
// Core Token Classes
// ============================================================================

case class Token(value: String, tokenType: TokenType, metadata: Map[String, Any] = Map.empty) {
  def withMetadata(entries: (String, Any)*): Token = {
    copy(metadata = metadata ++ entries)
  }
}

class MutableTokenBatch(val tokens: mutable.ListBuffer[Token] = mutable.ListBuffer.empty, private var _processed: Boolean = false) {
  def add(token: Token): Unit = {
    if (_processed) {
      throw new RuntimeException("Batch already processed")
    }
    tokens += token
  }

  def markProcessed(): Unit = {
    _processed = true
  }
}

// ============================================================================
// Generic Container Classes
// ============================================================================

class TokenContainer[+T](items: Seq[T]) {
  // Spec calls it getAll
  def getAll: Seq[T] = items

  // Spec calls it size
  def size: Int = items.size

  def mapTokens(func: T => String): Seq[String] = {
    items.map(func)
  }
}

class TokenSink[-T] {
  private val _received = mutable.ListBuffer.empty[Any] // Storing as Any to allow "supertype" behavior simulation if needed, but practically T is fine. Python uses Any.

  def receive(item: T): Unit = {
    _received += item
  }

  def drain(): List[Any] = {
    val result = _received.toList
    _received.clear()
    result
  }
}

class BivariantHandler[T](private var _value: T) {
  def get: T = _value

  def set(value: T): Unit = {
    _value = value
  }

  def transform(func: T => T): T = {
    _value = func(_value)
    _value
  }
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

abstract class BaseTokenizer[T] {
  def tokenize(value: T): Token

  def tokenizeBatch(values: Iterable[T]): Iterator[Token] = {
    values.iterator.map(tokenize)
  }
}

class StringTokenizer(val encoding: String = "utf-8", val normalizer: String => String = identity) extends BaseTokenizer[Any] {
  // In Python, input is StrOrBytes. Here we accept Any and check, or could use Either.
  // Using Any to be compatible with UniversalTokenizer's dispatch.

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case bytes: Array[Byte] => new String(bytes, encoding)
      case s: String => s
      case other => other.toString
    }

    val normalized = normalizer(strValue)
    Token(normalized, TokenType.STRING)
  }
}

class NumericTokenizer(
  val precision: Int = 6,
  val formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[Any] {
  // Accepts NumericT (int, float, Decimal)

  override def tokenize(value: Any): Token = {
    val strValue = value match {
      case d: BigDecimal => d.setScale(precision, scala.math.BigDecimal.RoundingMode.HALF_UP).toString
      case f: Float => f"%.${precision}f".format(f)
      case d: Double => f"%.${precision}f".format(d)
      case n: Number => n.toString // Int, Long, etc.
      case other => other.toString
    }

    Token(strValue, TokenType.NUMERIC, Map("original_type" -> value.getClass.getSimpleName))
  }
}

class TemporalTokenizer(val formatStr: Option[String] = None) extends BaseTokenizer[Any] {
  // Accepts LocalDateTime, LocalDate

  private val ISO_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE_TIME
  private val DATE_FORMAT = DateTimeFormatter.ISO_LOCAL_DATE

  // Custom formatter helper if formatStr is provided
  private def getFormatter: DateTimeFormatter = formatStr match {
      case Some(s) => DateTimeFormatter.ofPattern(s)
      case None => ISO_FORMAT // Default fallback, specific logic in tokenize
  }

  override def tokenize(value: Any): Token = {
    val (strValue, _) = value match {
      case dt: LocalDateTime => 
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(ISO_FORMAT)
        (dt.format(fmt), TokenType.TEMPORAL)
      case d: LocalDate =>
        val fmt = formatStr.map(DateTimeFormatter.ofPattern).getOrElse(DATE_FORMAT)
        (d.format(fmt), TokenType.TEMPORAL)
      case other => (other.toString, TokenType.STRING) // Should not happen given constraints, but safe fallback
    }
    Token(strValue, TokenType.TEMPORAL)
  }
}

// ============================================================================
// Advanced: Union Types and Overloads
// ============================================================================

class UniversalTokenizer {
  private val stringTokenizer = new StringTokenizer()
  private val numericTokenizer = new NumericTokenizer()
  private val temporalTokenizer = new TemporalTokenizer()

  // Overloads for type safety where possible
  def tokenize(value: String): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Array[Byte]): Token = stringTokenizer.tokenize(value)
  def tokenize(value: Int): Token = numericTokenizer.tokenize(value)
  def tokenize(value: Double): Token = numericTokenizer.tokenize(value)
  def tokenize(value: BigDecimal): Token = numericTokenizer.tokenize(value)
  def tokenize(value: LocalDateTime): Token = temporalTokenizer.tokenize(value)
  def tokenize(value: LocalDate): Token = temporalTokenizer.tokenize(value)

  // Spec calls this
